-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/sandoria/The_Generals_Secret.lua"]={["Path"]="scripts/quests/sandoria/The_Generals_Secret.lua",["SHA256"]="8c545e69996d96229dc278e4994f1189a666304145dcce952fc031e43780e83d",["Text"]="-----------------------------------\n-- A Sentry's Peril\n-- !addquest 0 60\n-- Curilla : !pos 27 0.1 0.1 233\n-- Hot Springs : !pos 444 -37 -18 139\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_GENERALS_SECRET)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item = xi.item.LYNX_BAGHNAKHS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.SANDORIA) >= 2\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Curilla'] = quest:progressEvent(55),\n\n            onEventFinish =\n            {\n                [55] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.CURILLAS_BOTTLE_EMPTY)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.CURILLAS_BOTTLE_FULL) then\n                        return quest:progressEvent(54)\n                    else\n                        return quest:progressEvent(53)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [54] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.CURILLAS_BOTTLE_FULL)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.HORLAIS_PEAK] =\n        {\n            ['Hot_Springs'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.CURILLAS_BOTTLE_EMPTY) then\n                        player:delKeyItem(xi.keyItem.CURILLAS_BOTTLE_EMPTY)\n                        return quest:keyItem(xi.keyItem.CURILLAS_BOTTLE_FULL)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Medicine_Woman.lua"]={["Path"]="scripts/quests/sandoria/The_Medicine_Woman.lua",["SHA256"]="0e63e4317885fbc9e353385f12ab562e0109c833f02dff4fb8f76ea0ad3de5b1",["Text"]="-----------------------------------\n-- The Medicine Woman\n-----------------------------------\n-- Log ID: 0, Quest ID: 30\n-- Abeaule : !pos -136 -2 56 231\n-- Amaura  : !pos -85 -6 89 230\n-----------------------------------\nlocal northernSandoriaID = zones[xi.zone.NORTHERN_SAN_DORIA]\nlocal southernSandoriaID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_MEDICINE_WOMAN)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 2100,\n    title    = xi.title.TRAVELING_MEDICINE_MAN,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_TRADER_IN_THE_FOREST) and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 3\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Abeaule'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(613)\n                    else\n                        return quest:progressEvent(615)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [613] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [615] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Abeaule'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.COLD_MEDICINE) then\n                        return quest:progressEvent(614)\n                    else\n                        return quest:messageText(northernSandoriaID.text.ABEAULE_DIALOG_HOME)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [614] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.COLD_MEDICINE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Amaura'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        player:hasKeyItem(xi.keyItem.AMAURAS_FORMULA) and\n                        npcUtil.tradeHasExactly(trade, { xi.item.MALBORO_VINE, xi.item.CHUNK_OF_ZINC_ORE, xi.item.INSECT_WING })\n                    then\n                        return quest:progressEvent(637)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local hasFormula = player:hasKeyItem(xi.keyItem.AMAURAS_FORMULA)\n                    local hasColdMedicine = player:hasKeyItem(xi.keyItem.COLD_MEDICINE)\n\n                    if\n                        not hasFormula and\n                        not hasColdMedicine\n                    then\n                        return quest:progressEvent(636)\n                    elseif hasFormula then\n                        return quest:messageText(southernSandoriaID.text.AMAURA_DIALOG_COMEBACK)\n                    elseif hasColdMedicine then\n                        return quest:messageText(southernSandoriaID.text.AMAURA_DIALOG_DELIVER)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [636] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.AMAURAS_FORMULA)\n                    end\n                end,\n\n                [637] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:delKeyItem(xi.keyItem.AMAURAS_FORMULA)\n                    npcUtil.giveKeyItem(player, xi.keyItem.COLD_MEDICINE)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Merchants_Bidding.lua"]={["Path"]="scripts/quests/sandoria/The_Merchants_Bidding.lua",["SHA256"]="bf8eb2262aa02bce67229d217974eb41527cdaf0578f2a02bc5102c52db6a215",["Text"]="-----------------------------------\n-- The Merchants Bidding\n-----------------------------------\n-- Log ID: 0, Quest ID: 69\n-----------------------------------\n-- Parvipon : !pos -169 -1 13 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_MERCHANTS_BIDDING)\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Parvipon'] = quest:progressEvent(90),\n\n            onEventFinish =\n            {\n                [90] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Parvipon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.RABBIT_HIDE, 3 } }) then\n                        return quest:progressEvent(89)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_MERCHANTS_BIDDING) == xi.questStatus.QUEST_ACCEPTED then\n                        return quest:event(88)\n                    else\n                        return quest:event(90, { [7] = 1 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [89] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                    end\n\n                    npcUtil.giveCurrency(player, 'gil', 120)\n                    player:confirmTrade()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Pickpocket.lua"]={["Path"]="scripts/quests/sandoria/The_Pickpocket.lua",["SHA256"]="3d862f1be6c5c1f5469554c0c86fac02fb9d9164aa44ac64572a8a4dfa73927a",["Text"]="-----------------------------------\n-- The Pickpocket\n-- Miene !pos 0 -4 -81 232\n-- Altiret !pos 21 -4 -65 232\n-- Esca !pos -624 -51 278 100\n-----------------------------------\nlocal portSandOriaID     = zones[xi.zone.PORT_SAN_DORIA]\nlocal northernSandOriaID = zones[xi.zone.NORTHERN_SAN_DORIA]\nlocal westRonfaureID     = zones[xi.zone.WEST_RONFAURE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_PICKPOCKET)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item = xi.item.LIGHT_AXE,\n    itemParams = { fromTrade = true },\n    title = xi.title.PICKPOCKET_PINCHER,\n}\n\nquest.sections =\n{\n    -- Speaking with the little elvaan girl, Miene, will activate a cutscene. You will see a burglar steal something from Altiret, one of the guards.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and vars.Prog == 0\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Miene'] = quest:progressEvent(502),\n\n            onEventFinish =\n            {\n                [502] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Informational: You can talk to nearby guards and by-standers, some will report having seen the thief allowing you to pick up the trail.\n    {\n        check = function(player, status, vars)\n            return\n                (status == xi.questStatus.QUEST_AVAILABLE and vars.Prog == 1) or\n                (status == xi.questStatus.QUEST_ACCEPTED and not player:hasItem(xi.item.GILT_GLASSES))\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Answald'] =       quest:message(portSandOriaID.text.PICKPOCKET_ANSWALD),\n            ['Artinien'] =      quest:message(portSandOriaID.text.PICKPOCKET_ARTINIEN),\n            ['Avandale'] =      quest:message(portSandOriaID.text.PICKPOCKET_AVANDALE),\n            ['Brifalien'] =     quest:message(portSandOriaID.text.PICKPOCKET_BRIFALIEN),\n            ['Comittie'] =      quest:message(portSandOriaID.text.PICKPOCKET_COMITTIE):oncePerZone(),\n            ['Coribalgeant'] =  quest:message(portSandOriaID.text.PICKPOCKET_CORIBALGEANT),\n            ['Crilde'] =        quest:message(portSandOriaID.text.PICKPOCKET_CRILDE),\n            ['Eaugouint'] =     quest:message(portSandOriaID.text.PICKPOCKET_EAUGOUINT),\n            ['Laucimercen'] =   quest:message(portSandOriaID.text.PICKPOCKET_LAUCIMERCEN),\n            ['Marquie'] =       quest:message(portSandOriaID.text.PICKPOCKET_MARQUIE),\n            ['Maunadolace'] =   quest:message(portSandOriaID.text.PICKPOCKET_MAUNADOLACE),\n            ['Meinemelle'] =    quest:message(portSandOriaID.text.PICKPOCKET_MEINEMELLE):oncePerZone(),\n            ['Meuxtajean'] =    quest:message(portSandOriaID.text.PICKPOCKET_MEUXTAJEAN),\n            ['Noquerelle'] =    quest:message(portSandOriaID.text.PICKPOCKET_NOQUERELLE),\n            ['Parcarin'] =      quest:message(portSandOriaID.text.PICKPOCKET_PARCARIN),\n            ['Rielle'] =        quest:message(portSandOriaID.text.PICKPOCKET_RIELLE),\n            ['Sheridan'] =      quest:message(portSandOriaID.text.PICKPOCKET_SHERIDAN),\n            ['Solgierte'] =     quest:message(portSandOriaID.text.PICKPOCKET_SOLGIERTE),\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Aurege'] =        quest:message(northernSandOriaID.text.PICKPOCKET_AUREGE):importantOnce(),\n            ['Gilipese'] =      quest:message(northernSandOriaID.text.PICKPOCKET_GILIPESE),\n            ['Guilberdrier'] =  quest:message(northernSandOriaID.text.PICKPOCKET_GUILBERDRIER),\n            ['Maurinne'] =      quest:sequence(\n                                    { text = northernSandOriaID.text.PICKPOCKET_MAURINNE, wait = 1000 },\n                                    { text = northernSandOriaID.text.PICKPOCKET_MAURINNE + 1, face = 82, wait = 2000 },\n                                    { face = 115 }\n                                ),\n            ['Pepigort'] =      quest:message(northernSandOriaID.text.PICKPOCKET_PEPIGORT),\n            ['Rodaillece'] =    quest:message(northernSandOriaID.text.PICKPOCKET_RODAILLECE):importantOnce(),\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Aaveleon'] =      quest:message(westRonfaureID.text.PICKPOCKET_AAVELEON),\n            ['Adalefont'] =     quest:message(westRonfaureID.text.PICKPOCKET_ADALEFONT),\n            ['Colmaie'] =       quest:message(westRonfaureID.text.PICKPOCKET_COLMAIE),\n            ['Gachemage'] =     quest:message(westRonfaureID.text.PICKPOCKET_GACHEMAGE),\n            ['Laillera'] =      quest:message(westRonfaureID.text.PICKPOCKET_LAILLERA),\n            ['Palcomondau'] =   quest:message(westRonfaureID.text.PICKPOCKET_PALCOMONDAU),\n            ['Zovriace'] =      quest:message(westRonfaureID.text.PICKPOCKET_ZOVRIACE),\n        },\n    },\n\n    -- After the cutscene ends, speak with Altiret. He asks you to retrieve his wife's glasses for him, since he cannot leave his post.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and vars.Prog == 1\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Miene'] = quest:event(554),\n            ['Altiret'] = quest:progressEvent(547),\n\n            onEventFinish =\n            {\n                [547] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 0)\n                end,\n            },\n        },\n    },\n\n    -- Speak to Miene again to get a quest item Eagle Button.\n    -- Travel to (F-6) in West Ronfaure. You will find Esca in the tower there.\n    -- Speak with her, and she will deny any accusation, demanding proof.\n    -- Trade Esca the Eagle Button and she will admit her guilt. She then gives you the Gilt Glasses.\n    -- Return to Port San d'Oria and trade the Gilt Glasses to Altiret for your reward.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Altiret'] =\n            {\n                onTrigger = quest:event(547),\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.GILT_GLASSES, 1 } }) then\n                        return quest:progressEvent(550)\n                    else\n                        return quest:event(551)\n                    end\n                end,\n            },\n\n            ['Miene'] =\n            {\n                onTrigger = function(player, npc)\n                    local stage = quest:getVar(player, 'Stage')\n\n                    if stage == 0 then\n                        if player:getFreeSlotsCount() > 0 then\n                            return quest:progressEvent(549)\n                        else\n                            return quest:event(552)\n                        end\n                    else\n                        if\n                            player:getFreeSlotsCount() > 0 and\n                            not player:hasItem(xi.item.EAGLE_BUTTON) and\n                            not player:hasItem(xi.item.GILT_GLASSES)\n                        then\n                            -- Reaquire the button\n                            return quest:progressEvent(611)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [549] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.EAGLE_BUTTON) then\n                        quest:setVar(player, 'Stage', 1)\n                    end\n                end,\n\n                [611] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.EAGLE_BUTTON)\n                end,\n\n                [550] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Esca'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasItem(xi.item.GILT_GLASSES) then\n                        return quest:event(123)\n                    else\n                        return quest:event(120)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.EAGLE_BUTTON, 1 } }) then\n                        return quest:progressEvent(121)\n                    end\n\n                    return quest:event(122)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [121] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.GILT_GLASSES, { fromTrade = true }) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Completed quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Altiret'] = quest:event(580),\n        },\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Esca'] = quest:event(123),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Rivalry.lua"]={["Path"]="scripts/quests/sandoria/The_Rivalry.lua",["SHA256"]="6eceb1245733c5c5b6e5e0a0ef39e799781a1f85859924b4f4f1dcc3cc148617",["Text"]="-----------------------------------\n-- The Rivalry\n-- Log ID: 0, Quest ID: 75\n-- Gallijaux !pos -18 -2 -45 232\n-----------------------------------\nlocal portSandOriaID = zones[xi.zone.PORT_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_RIVALRY)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.LU_SHANGS_FISHING_ROD,\n    keyItem  = xi.keyItem.TESTIMONIAL,\n    title    = xi.title.CARP_DIEM,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_COMPETITION) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Ufanne'] = quest:event(310),\n\n            ['Gallijaux'] = quest:progressEvent(300, xi.item.MOAT_CARP_1, xi.item.FOREST_CARP),\n\n            onEventFinish =\n            {\n                [300] = function(player, csid, option, npc)\n                    if option == 700 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Gallijaux'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:messageName(portSandOriaID.text.GALLIJAUX_CARP_STATUS, 0, player:getCharVar('carpsTraded'), 0, 0, true, false) -- TODO: The number that Gallijaux reports increases over time and eventually resets back to 0 before starting to tick back up.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local count        = trade:getItemCount()\n                    local moatCarp     = trade:getItemQty(xi.item.MOAT_CARP_1)\n                    local forestCarp   = trade:getItemQty(xi.item.FOREST_CARP)\n                    local fishCountVar = player:getCharVar('carpsTraded')\n                    local totalFish    = moatCarp + forestCarp + fishCountVar\n\n                    if moatCarp + forestCarp > 0 and moatCarp + forestCarp == count then\n                        if totalFish >= 10000 then\n                            player:setLocalVar('FishTraded', totalFish) -- Used to transfer the variable into oneventfinish\n                            player:setLocalVar('GilToReward', moatCarp * 10 + forestCarp * 15) -- Forces the gil reward to happen AFTER the event like in captures\n                            return quest:progressEvent(303)\n                        else\n                            player:setLocalVar('FishTraded', totalFish)\n                            player:setLocalVar('GilToReward', moatCarp * 10 + forestCarp * 15) -- Forces the gil reward to happen AFTER the event like in captures\n                            return quest:progressEvent(301)\n                        end\n                    end\n                end,\n            },\n\n            ['Joulet'] = quest:messageName(portSandOriaID.text.JOULET_HELP_OTHER_BROTHER, 0, 0, 0, 0, true, false),\n\n            ['Ufanne'] =\n            {\n                onTrigger = function(player, npc)\n                    local fishCount = player:getCharVar('carpsTraded')\n                    local cycle     = player:getLocalVar('Cycle')\n\n                    -- NPC cycles dialogue\n                    if cycle == 0 then\n                        player:setLocalVar('Cycle', 1)\n                        return quest:event(309, 0, 0, fishCount)\n                    elseif cycle == 1 then\n                        player:setLocalVar('Cycle', 0)\n                        return quest:event(310)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [301] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    player:setCharVar('carpsTraded', player:getLocalVar('FishTraded'))  -- As per captures this char var persists for the life of the character\n                    npcUtil.giveCurrency(player, 'gil', player:getLocalVar('GilToReward')) -- Ensures that gil is rewarded after the CS\n                    player:addFame(xi.fameArea.SANDORIA, 10)\n                end,\n\n                [303] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:setCharVar('carpsTraded', player:getLocalVar('FishTraded'))  -- As per captures this char var persists for the life of the character\n                        npcUtil.giveCurrency(player, 'gil', player:getLocalVar('GilToReward')) -- Ensures that gil is rewarded after the CS\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n\n            -- The player may continue to trade carps to Gallijaux even after obtaining Lu Shang.\n            ['Gallijaux'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:messageName(portSandOriaID.text.GALLIJAUX_CARP_STATUS, 0, player:getCharVar('carpsTraded'), 0, 0, true, false) -- TODO: The number that Gallijaux reports increases over time and eventually resets back to 0 before starting to tick back up.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local count        = trade:getItemCount()\n                    local moatCarp     = trade:getItemQty(xi.item.MOAT_CARP_1)\n                    local forestCarp   = trade:getItemQty(xi.item.FOREST_CARP)\n                    local fishCountVar = player:getCharVar('carpsTraded')\n                    local totalFish    = moatCarp + forestCarp + fishCountVar\n\n                    if moatCarp + forestCarp > 0 and moatCarp + forestCarp == count then\n                        player:setLocalVar('FishTraded', totalFish)\n                        player:setLocalVar('GilToReward', moatCarp * 10 + forestCarp * 15) -- Forces the gil reward to happen AFTER the event like in captures\n                        return quest:progressEvent(301)\n                    end\n                end,\n            },\n\n            ['Joulet'] = quest:messageName(portSandOriaID.text.JOULET_HELP_OTHER_BROTHER, 0, 0, 0, 0, true, false),\n\n            ['Ufanne'] =\n            {\n                onTrigger = function(player, npc)\n                    local fishCount = player:getCharVar('carpsTraded')\n                    local cycle     = player:getLocalVar('Cycle')\n\n                    -- NPC cycles dialogue\n                    if cycle == 0 then\n                        player:setLocalVar('Cycle', 1)\n                        return quest:event(309, 0, 0, fishCount)\n                    elseif cycle == 1 then\n                        player:setLocalVar('Cycle', 0)\n                        return quest:event(310)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [301] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    player:setCharVar('carpsTraded', player:getLocalVar('FishTraded'))  -- As per captures this char var persists for the life of the character\n                    npcUtil.giveCurrency(player, 'gil', player:getLocalVar('GilToReward'))\n                    player:addFame(xi.fameArea.SANDORIA, 10)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Rumor.lua"]={["Path"]="scripts/quests/sandoria/The_Rumor.lua",["SHA256"]="6967aec17267ef068fc96229c6d8dfa9ce5eb1e6e334d0eea825bcd5278cd77c",["Text"]="-----------------------------------\n-- The Rumor\n-----------------------------------\n-- Log ID: 0, Quest ID: 61\n-----------------------------------\n-- Novalmauge !pos 70 -24 21 167\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_RUMOR)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.SCROLL_OF_DRAIN,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 3 and\n                player:getMainLvl() >= 5 -- Level requirement added in the March 8, 2007 update: https://www.playonline.com/pcd/update/ff11us/20070308c2bbd1/detail.html\n        end,\n\n        [xi.zone.BOSTAUNIEUX_OUBLIETTE] =\n        {\n            ['Novalmauge'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(13)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [13] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        }\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BOSTAUNIEUX_OUBLIETTE] =\n        {\n            ['Novalmauge'] =\n            {\n                onTrigger = quest:event(11),\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.VIAL_OF_BEASTMAN_BLOOD) then\n                        return quest:progressEvent(12)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BOSTAUNIEUX_OUBLIETTE] =\n        {\n            ['Novalmauge'] = quest:event(14):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Seamstress.lua"]={["Path"]="scripts/quests/sandoria/The_Seamstress.lua",["SHA256"]="239d30d2c9835efd664507e6ba9989ec92bf3e3c8e623dda0219c2afb36ecfdb",["Text"]="-----------------------------------\n-- The Seamstress\n-----------------------------------\n-- Log ID: 0, Quest ID: 5\n-- Hanaa Punaa : !pos -179.726 -8.8 27.574 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_SEAMSTRESS)\n\nquest.reward =\n{\n    fame = 10,\n    fameArea = xi.fameArea.SANDORIA,\n    -- Repeatable Items handled within the Trigger:\n    -- item = xi.item.LEATHER_GLOVES,\n    -- title = xi.title.SILENCER_OF_THE_LAMBS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(528)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(531)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [528] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [531] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] = quest:progressEvent(529),\n        },\n    },\n\n    -- These functions check the status of ~= xi.questStatus.QUEST_AVAILABLE to support repeating\n    -- the quest.  Does not have to be flagged again to complete an additional time.\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.SHEEPSKIN, 3 } }) then\n                        return quest:progressEvent(530)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [530] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.LEATHER_GLOVES, { fromTrade = true }) then\n                        player:confirmTrade()\n                        player:addTitle(xi.title.SILENCER_OF_THE_LAMBS)\n                        if not player:hasCompletedQuest(quest.areaId, quest.questId) then\n                            quest:complete(player)\n                        else\n                            player:addFame(xi.fameArea.SANDORIA, 10)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and player:getFameLevel(xi.fameArea.SANDORIA) < 2\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hanaa_Punaa'] = quest:event(590):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Setting_Sun.lua"]={["Path"]="scripts/quests/sandoria/The_Setting_Sun.lua",["SHA256"]="d5e3068dc77429cebbd6959d465f7bfccc17054927c3c596308e77ae89e17807",["Text"]="-----------------------------------\n-- The Setting Sun\n-----------------------------------\n-- LogID: 0 QuestID: 72\n-----------------------------------\n-- Vamorcote: !pos -137.070 10.999 161.855 231\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_SETTING_SUN)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.SANDORIA,\n    gil      = 10000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 5 and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.BLACKMAIL)\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Vamorcote'] = quest:progressEvent(654, { [1] = xi.item.ENGRAVED_KEY, [2] = xi.item.ENGRAVED_KEY }),\n\n            onEventFinish =\n            {\n                [654] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Vamorcote'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.ENGRAVED_KEY) then\n                        return quest:progressEvent(658)\n                    end\n                end,\n\n                onTrigger = quest:event(655, { [2] = xi.item.ENGRAVED_KEY }),\n            },\n            onEventFinish =\n            {\n                [658] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:needToZone()\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Vamorcote'] = quest:event(659):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Sweetest_Things.lua"]={["Path"]="scripts/quests/sandoria/The_Sweetest_Things.lua",["SHA256"]="28b46814a0348fcd6905f386d00715950a6d0f8247faa3feea7cd72d04e551fe",["Text"]="-----------------------------------\n-- The Sweetest Things\n-----------------------------------\n-- Log ID: 0, Quest ID: 8\n-- Raimbroy : !pos -141 -3 34.6 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_SWEETEST_THINGS)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.SANDORIA,\n    title    = xi.title.APIARIST,\n}\n\nlocal raimbroyOnTrade = function(player, npc, trade)\n    if npcUtil.tradeHasExactly(trade, { { xi.item.POT_OF_HONEY, 5 } }) then\n        return quest:progressEvent(535, 400 * xi.settings.main.GIL_RATE)\n    else\n        return quest:event(522)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 2\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Raimbroy'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(532)\n                    elseif questProgress == 1 then\n                        return quest:event(533)\n                    elseif questProgress == 2 then\n                        return quest:event(534)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [532] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [533] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n\n                [534] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Raimbroy'] =\n            {\n                onTrade   = raimbroyOnTrade,\n                onTrigger = quest:event(536),\n            },\n\n            onEventFinish =\n            {\n                [535] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        -- Note: Gil is mentioned in the event, so add silently here.  Also,\n                        -- we need to implement a latch, since both event finishes will trigger\n                        -- after the complete.\n\n                        player:addGil(400 * xi.settings.main.GIL_RATE)\n                        quest:setLocalVar(player, 'firstComplete', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Raimbroy'] =\n            {\n                onTrade   = raimbroyOnTrade,\n                onTrigger = quest:event(537),\n            },\n\n            onEventFinish =\n            {\n                [535] = function(player, csid, option, npc)\n                    if quest:getLocalVar(player, 'firstComplete') == 0 then\n                        player:confirmTrade()\n\n                        player:addTitle(xi.title.APIARIST)\n                        player:addGil(400 * xi.settings.main.GIL_RATE)\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                    else\n                        quest:setLocalVar(player, 'firstComplete', 0)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Trader_in_the_Forest.lua"]={["Path"]="scripts/quests/sandoria/The_Trader_in_the_Forest.lua",["SHA256"]="f53868bd8a3f5099188972424ba5586793ea063abace9ce0069ae0b06e724238",["Text"]="-----------------------------------\n-- The Trader in the Forest\n-----------------------------------\n-- Log ID: 0, Quest ID: 7\n-- Abeaule : !pos -136 -2 56 231\n-- Phairet : !pos -57 -2 -502 100\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_TRADER_IN_THE_FOREST)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.ROBE,\n    title    = xi.title.GREEN_GROCER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Abeaule'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(524)\n                    else\n                        return quest:progressEvent(592)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [524] = function(player, csid, option, npc)\n                    if option == 0 and npcUtil.giveItem(player, xi.item.SUPPLIES_ORDER) then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [592] = function(player, csid, option, npc)\n                    if option == 0 and npcUtil.giveItem(player, xi.item.SUPPLIES_ORDER) then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Abeaule'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.CLUMP_OF_BATAGREENS) then\n                        return quest:progressEvent(525)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(593)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [525] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n\n                [593] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveItem(player, xi.item.SUPPLIES_ORDER)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED or status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WEST_RONFAURE] =\n        {\n            ['Phairet'] =\n            {\n                -- Phairet will continue to accept Supplies Order after the quest has been\n                -- completed, should the player have purchased a batagreen, or picked up\n                -- an additional order prior to completion.\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SUPPLIES_ORDER) then\n                        return quest:progressEvent(124)\n                    elseif\n                        npcUtil.tradeHas(trade, { { 'gil', 50 } }) and\n                        npcUtil.giveItem(player, xi.item.CLUMP_OF_BATAGREENS)\n                    then\n                        player:confirmTrade()\n\n                    -- Rejection for invalid trades only occurs after supplies order has been\n                    -- traded, or the quest has been completed.\n                    elseif\n                        player:hasCompletedQuest(quest.areaId, quest.questId) or\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        return quest:progressEvent(125)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        player:hasCompletedQuest(quest.areaId, quest.questId) or\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        return quest:progressEvent(127, xi.item.CLUMP_OF_BATAGREENS)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [124] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.CLUMP_OF_BATAGREENS) then\n                        player:confirmTrade()\n\n                        if player:getQuestStatus(quest.areaId, quest.questId) == xi.questStatus.QUEST_ACCEPTED then\n                            quest:setVar(player, 'Prog', 2)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/The_Vicasques_Sermon.lua"]={["Path"]="scripts/quests/sandoria/The_Vicasques_Sermon.lua",["SHA256"]="7bf6d29573ca4277d8438eda2718104143b4c75b56df1febb168dd424e07cf05",["Text"]="-----------------------------------\n-- The Vicasque's Sermon\n-----------------------------------\n-- Log ID: 0, Quest ID: 9\n-- Abioleget : !pos 128.771 0 118.538 231\n-- Andelain  : !pos 664.231 -12.849 -539.413 101\n-----------------------------------\nlocal eastRonfaureID     = zones[xi.zone.EAST_RONFAURE]\nlocal northernSandoriaID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_VICASQUES_SERMON)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.BRASS_RING,\n    title    = xi.title.THE_BENEVOLENT_ONE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.WATERS_OF_THE_CHEVAL)\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Abioleget'] = quest:progressEvent(589),\n\n            onEventFinish =\n            {\n                [589] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Abioleget'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { 'gil', 70 } }) then\n                        return quest:progressEvent(591)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(600)\n                    else\n                        return quest:messageName(northernSandoriaID.text.WILL_PROVIDE_PITTANCE, xi.item.POD_OF_BLUE_PEAS, 70)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [591] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.POD_OF_BLUE_PEAS) then\n                        player:confirmTrade()\n                    end\n                end,\n\n                [600] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.EAST_RONFAURE] =\n        {\n            ['Andelain'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.POD_OF_BLUE_PEAS) then\n                        if quest:getVar(player, 'Prog') == 1 then\n                            return quest:messageName(eastRonfaureID.text.APPRECIATE_OFFER_DECLINE, xi.item.POD_OF_BLUE_PEAS)\n                        else\n                            player:messageSpecial(eastRonfaureID.text.THANKS_TO_GODDESS)\n                            return quest:progressEvent(19)\n                        end\n                    else\n                        return quest:messageSpecial(eastRonfaureID.text.CANNOT_ACCEPT_ALMS)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(19)\n                    else\n                        return quest:messageName(eastRonfaureID.text.MAY_ONLY_EAT, xi.item.POD_OF_BLUE_PEAS)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [19] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        player:confirmTrade()\n                        quest:setVar(player, 'Prog', 1)\n                    end\n\n                    player:messageSpecial(eastRonfaureID.text.GATES_OF_PARADISE_OPEN)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Tigers_Teeth.lua"]={["Path"]="scripts/quests/sandoria/Tigers_Teeth.lua",["SHA256"]="37194c2dbc2c93e0776cb29f7fa10c9f80e21177cefced5ae065c16ce3bd3889",["Text"]="-----------------------------------\n-- Tigers Teeth\n-----------------------------------\n-- LogID: 0 QuestID: 23\n-- Taumila : !pos -140 -6 -8 230\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.TIGERS_TEETH)\n\nquest.reward =\n{\n    gil   = 2100,\n    title = xi.title.FANG_FINDER,\n    fame  = 16,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 3\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Taumila'] = quest:progressEvent(574),\n\n            onEventFinish =\n            {\n                [574] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Taumila'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.BLACK_TIGER_FANG, 3 } }) then\n                        return quest:progressEvent(572)\n                    else\n                        return quest:event(573)\n                    end\n                end,\n\n                onTrigger = quest:event(575):replaceDefault(),\n            },\n\n            onEventFinish =\n            {\n                [572] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Taumila'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.BLACK_TIGER_FANG, 3 } }) then\n                        quest:setLocalVar(player, 'Option', 1)\n                        return quest:progressEvent(572)\n                    else\n                        return quest:event(573)\n                    end\n                end,\n\n                onTrigger = quest:event(571):replaceDefault(),\n            },\n\n            onEventFinish =\n            {\n                [572] = function(player, csid, option, npc)\n                    if\n                        quest:getLocalVar(player, 'Option') == 1 and\n                        npcUtil.giveCurrency(player, 'gil', 2100)\n                    then\n                        quest:setLocalVar(player, 'Option', 0)\n                        player:confirmTrade()\n                        player:addFame(xi.fameArea.SANDORIA, 16)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Trouble_at_the_Sluice.lua"]={["Path"]="scripts/quests/sandoria/Trouble_at_the_Sluice.lua",["SHA256"]="f544d384dc848b209c33778a4e92b00221d374f4b70e16d145a1d1072c567cfb",["Text"]="-----------------------------------\n-- Trouble at the Sluice\n-----------------------------------\n-- Log ID: 0, Quest ID: 68\n-----------------------------------\n-- Belgidiveau : !pos -98 0 69 231\n-- Novalmauge  : !pos 70 -24 21 167\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.TROUBLE_AT_THE_SLUICE)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.SANDORIA,\n    item     = xi.item.HEAVY_AXE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_RUMOR) == xi.questStatus.QUEST_COMPLETED and\n                player:getFameLevel(xi.fameArea.SANDORIA) >= 3\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Belgidiveau'] = quest:progressEvent(57),\n\n            onEventFinish =\n            {\n                [57] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                not player:hasKeyItem(xi.keyItem.NEUTRALIZER) and\n                vars.Prog == 0\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Belgidiveau'] = quest:event(55),\n        },\n\n        [xi.zone.BOSTAUNIEUX_OUBLIETTE] =\n        {\n            ['Novalmauge'] = quest:progressEvent(15),\n\n            onEventFinish =\n            {\n                [15] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                not player:hasKeyItem(xi.keyItem.NEUTRALIZER) and\n                vars.Prog == 1\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Belgidiveau'] = quest:event(55),\n        },\n\n        [xi.zone.BOSTAUNIEUX_OUBLIETTE] =\n        {\n            ['Novalmauge'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.DAHLIA) then\n                        return quest:progressEvent(17)\n                    end\n                end,\n\n                onTrigger = quest:event(16),\n            },\n\n            onEventFinish =\n            {\n                [17] = function(player, csid, option, npc)\n                    if npcUtil.giveKeyItem(player, xi.keyItem.NEUTRALIZER) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.NEUTRALIZER)\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Belgidiveau'] = quest:progressEvent(56),\n\n            onEventFinish =\n            {\n                [56] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.NEUTRALIZER)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Warding_Vampires.lua"]={["Path"]="scripts/quests/sandoria/Warding_Vampires.lua",["SHA256"]="97b4bf038945c44037f7bafe13e577e879194a12cd81a52f23671210dfc31532",["Text"]="-----------------------------------\n-- Warding Vampires\n-----------------------------------\n-- Log ID: 0, Quest ID: 79\n-----------------------------------\n-- Maloquedil : !pos 35 0.1 60 231\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.WARDING_VAMPIRES)\n\nquest.reward =\n{\n    fame     = 16,\n    fameArea = xi.fameArea.SANDORIA,\n    title    = xi.title.VAMPIRE_HUNTER_D_MINUS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Maloquedil'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getFameLevel(xi.fameArea.SANDORIA) >= 3 then\n                        return quest:progressEvent(24)\n                    else\n                        return quest:event(21)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [24] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Maloquedil'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.BULB_OF_SHAMAN_GARLIC, 2 } }) then\n                        return quest:progressEvent(23)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.WARDING_VAMPIRES) == xi.questStatus.QUEST_ACCEPTED then\n                        return quest:event(22)\n                    else\n                        return quest:event(24, { [7] = 1 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [23] = function(player, csid, option, npc)\n                    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.WARDING_VAMPIRES) == xi.questStatus.QUEST_ACCEPTED then\n                        quest:complete(player)\n                    else\n                        player:addFame(xi.fameArea.SANDORIA, 16)\n                    end\n\n                    npcUtil.giveCurrency(player, 'gil', 900)\n                    player:confirmTrade()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/sandoria/Waters_of_the_Cheval.lua"]={["Path"]="scripts/quests/sandoria/Waters_of_the_Cheval.lua",["SHA256"]="5bcdde5e29e28f599779ae794ced26d16df9fb9a36d1e506e30347e2cd251800",["Text"]="-----------------------------------\n-- Waters of the Cheval\n-- Miageau !pos 115 0 108 231\n-- Nouveil !pos 123 0 106 231\n-- Cheval_River !pos 223 -58 426 101\n-----------------------------------\nlocal eastRonfaureID     = zones[xi.zone.EAST_RONFAURE]\nlocal northernSandoriaID = zones[xi.zone.NORTHERN_SAN_DORIA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.SANDORIA, xi.quest.id.sandoria.WATERS_OF_THE_CHEVAL)\n\nquest.reward =\n{\n    fame       = 20,\n    fameArea   = xi.fameArea.SANDORIA,\n    item       = xi.item.WING_PENDANT,\n    itemParams = { fromTrade = true },\n    title      = xi.title.THE_PURE_ONE,\n}\n\nquest.sections =\n{\n    -- Speak with Miageau (L-7) just past the entrance to the Cathedral.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Miageau'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(504)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [504] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Buy a Blessed Waterskin by trading 10g to Nouveil (to your right).\n    -- Trade the waterskin to the Cheval River target East Ronfaure (H-5) (top of the river) to receive Cheval Water.\n    -- Trade Cheval Water to Miageau.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Miageau'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.SKIN_OF_CHEVAL_RIVER_WATER) then\n                        return quest:progressEvent(515)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:hasItem(xi.item.BLESSED_WATERSKIN) then\n                        return quest:event(512)\n                    else\n                        return quest:event(519)\n                    end\n                end,\n            },\n\n            ['Nouveil'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { 'gil', 10 } }) then\n                        player:messageSpecial(northernSandoriaID.text.YOU_DONATE_GIL)\n                        return quest:progressEvent(571)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:hasItem(xi.item.SKIN_OF_CHEVAL_RIVER_WATER) then\n                        return quest:event(573)\n                    elseif player:hasItem(xi.item.BLESSED_WATERSKIN) then\n                        return quest:event(572)\n                    else\n                        return quest:event(575)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [515] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n\n                [571] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.BLESSED_WATERSKIN, { fromTrade = true }) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.EAST_RONFAURE] =\n        {\n            ['Cheval_River'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHas(trade, xi.item.BLESSED_WATERSKIN) and\n                        npcUtil.giveItem(player, xi.item.SKIN_OF_CHEVAL_RIVER_WATER, { silent = true, fromTrade = true })\n                    then\n                        player:confirmTrade()\n                        return quest:messageSpecial(eastRonfaureID.text.CHEVAL_RIVER_WATER, xi.item.SKIN_OF_CHEVAL_RIVER_WATER)\n                    end\n                end,\n\n                onTrigger = quest:messageSpecial(eastRonfaureID.text.BLESSED_WATERSKIN),\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/A_Greeting_Cardian.lua"]={["Path"]="scripts/quests/windurst/A_Greeting_Cardian.lua",["SHA256"]="23324e0d354776f1c20d6a82cf3b0d73c150018307209a2cab62a435bf28eeb3",["Text"]="-----------------------------------\n-- A Greeting Cardian\n-----------------------------------\n-- Log ID: 2, Quest ID: 43\n-- !addquest 2 43\n-- Kororo           : !pos -11.883 -2.750 5.508 241\n-- Spare One        : !pos -8.201 -2.750 10.018 241\n-- Boizo-Naizo      : !pos -9.581 -2.750 -26.062 241\n-- Five of Diamonds : !pos -220.954 0.999 -122.708 239\n-- Five of Hearts   : !pos 126.369 -2.002 45.531 238\n-- Five of Clubs    : !pos 97.481 -4.000 151.498 240\n-- Five of Spades   : !pos -478.100 -32.120 47.394 118\n-----------------------------------\n-- Only Spare One offers the greeting menu. Event 295 arms the quest.\n-- The log stays empty until Kororo's offer is accepted. He offers it after a zone change.\n-- Event 296 is a nudge, not the offer. The greeting chosen on 295 is replayed later.\n-----------------------------------\nlocal buburimuID = zones[xi.zone.BUBURIMU_PENINSULA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.A_GREETING_CARDIAN)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.TOURMALINE_EARRING,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_2000) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 3\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Kororo'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Points at Spare One until a greeting is taught.\n                    if quest:getVar(player, 'Greeting') == 0 then\n                        return quest:event(296)\n                    end\n\n                    -- The offer needs the zone change and the timer. Kororo gives his default line until then.\n                    if\n                        not quest:getMustZone(player) and\n                        GetSystemTime() >= quest:getVar(player, 'Wait')\n                    then\n                        return quest:progressEvent(298)\n                    end\n                end,\n            },\n\n            ['Spare_One'] =\n            {\n                onTrigger = function(player, npc)\n                    local greeting = quest:getVar(player, 'Greeting')\n\n                    -- Spare One repeats the greeting he was taught.\n                    if greeting ~= 0 then\n                        return quest:event(495, 0, greeting)\n                    end\n\n                    return quest:progressEvent(295)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [295] = function(player, csid, option, npc)\n                    -- The menu offers three greetings. Escaping the cutscene teaches nothing.\n                    if option < 1 or option > 3 then\n                        return\n                    end\n\n                    quest:setVar(player, 'Greeting', option)\n                    quest:setVar(player, 'Wait', GetSystemTime() + 60) -- 1 minute wait time\n                    quest:setMustZone(player)\n                end,\n\n                [298] = function(player, csid, option, npc)\n                    -- Declining changes nothing. The offer can be taken again.\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BUBURIMU_PENINSULA] =\n        {\n            ['Five_of_Spades'] =\n            {\n                onTrigger = function(player, npc)\n                    local greeting = quest:getVar(player, 'Greeting')\n\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(1, xi.zone.BUBURIMU_PENINSULA, greeting)\n                    end\n\n                    -- Five of Spades keeps the taught greeting until Kororo corrects him.\n                    return quest:messageName(buburimuID.text.FIVEOFSPADES_GREETING_OFFSET + greeting)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Five_of_Clubs'] = quest:event(448),\n        },\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Five_of_Diamonds'] = quest:event(339),\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Five_of_Hearts'] = quest:event(686),\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Boizo-Naizo'] = quest:event(302),\n\n            ['Kororo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(303)\n                    end\n\n                    return quest:event(299)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [303] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Boizo-Naizo'] = quest:event(307),\n            ['Kororo']      = quest:event(304),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/A_Pose_by_Any_Other_Name.lua"]={["Path"]="scripts/quests/windurst/A_Pose_by_Any_Other_Name.lua",["SHA256"]="9d982910aa2dd877237ef552ec27f1885381000dc3b7a2ed2324182887f63655",["Text"]="-----------------------------------\n-- A Pose By Any Other Name\n-- Log ID: 2, Quest ID: 7\n-- Angelica !pos -64 -9.25 -9 238\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.A_POSE_BY_ANY_OTHER_NAME)\n\nlocal poseItems =\n{\n    [xi.job.WAR] = xi.item.BRONZE_HARNESS,\n    [xi.job.MNK] = xi.item.ROBE,\n    [xi.job.WHM] = xi.item.TUNIC,\n    [xi.job.BLM] = xi.item.TUNIC,\n    [xi.job.RDM] = xi.item.TUNIC,\n    [xi.job.THF] = xi.item.LEATHER_VEST,\n    [xi.job.PLD] = xi.item.BRONZE_HARNESS,\n    [xi.job.DRK] = xi.item.BRONZE_HARNESS,\n    [xi.job.BST] = xi.item.LEATHER_VEST,\n    [xi.job.BRD] = xi.item.ROBE,\n    [xi.job.RNG] = xi.item.LEATHER_VEST,\n    [xi.job.SAM] = xi.item.KENPOGI,\n    [xi.job.NIN] = xi.item.KENPOGI,\n    [xi.job.DRG] = xi.item.BRONZE_HARNESS,\n    [xi.job.SMN] = xi.item.TUNIC,\n    [xi.job.BLU] = xi.item.ROBE,\n    [xi.job.COR] = xi.item.BRONZE_HARNESS,\n    [xi.job.PUP] = xi.item.TUNIC,\n    [xi.job.DNC] = xi.item.LEATHER_VEST,\n    [xi.job.SCH] = xi.item.TUNIC,\n    [xi.job.GEO] = xi.item.TUNIC,\n    [xi.job.RUN] = xi.item.BRONZE_HARNESS,\n}\n\nlocal poseGear =\n{\n    [xi.item.BRONZE_HARNESS] = 1,\n    [xi.item.ROBE]           = 2,\n    [xi.item.TUNIC]          = 3,\n    [xi.item.LEATHER_VEST]   = 4,\n    [xi.item.KENPOGI]        = 6,\n}\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.WINDURST,\n    item = xi.item.COPY_OF_ANCIENT_BLOOD,\n    title = xi.title.SUPER_MODEL,\n    keyItem = xi.keyItem.ANGELICAS_AUTOGRAPH,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:needToZone() == false\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Angelica'] =\n            {\n                onTrigger = function(player, npc)\n                    local desiredBody = poseItems[player:getMainJob()]\n                    local currentBody = player:getEquipID(xi.slot.BODY)\n\n                    if currentBody ~= desiredBody then\n                        if quest:getVar(player, 'Option') == 0 then\n                            return quest:progressEvent(90)\n                        else\n                            return quest:progressEvent(91)\n                        end\n                    else\n                        return quest:event(86):setPriority(101) -- If the player is wearing the requested body for their job Angelica will only return event 86 intead of cycling between 86 and 87.\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [90] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Option', 0)\n                    elseif option == 2 then\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n\n                [91] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Angelica'] =\n            {\n                onTrigger = function(player, npc)\n                    local requestedBody = poseItems[player:getMainJob()]\n\n                    quest:setVar(player, 'Wait', GetSystemTime() + 3600) -- 1 Hour\n                    quest:setVar(player, 'Prog', requestedBody)\n                    return quest:progressEvent(92, 0, xi.item.BRONZE_HARNESS, xi.item.ROBE, xi.item.TUNIC, xi.item.LEATHER_VEST, xi.item.ROBE, xi.item.KENPOGI) -- Job check seems to be baked into the DAT.\n                end,\n            },\n        },\n    },\n\n    -- Section: Finish quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog ~= 0\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Angelica'] =\n            {\n                onTrigger = function(player, npc)\n                    local requestedBody = quest:getVar(player, 'Prog')\n\n                    if quest:getVar(player, 'Wait') >= GetSystemTime() then -- Under time. Quest completed.\n                        if player:getEquipID(xi.slot.BODY) == requestedBody then\n                            return quest:progressEvent(96)\n                        else\n                            return quest:progressEvent(94, poseGear[quest:getVar(player, 'Prog')], xi.item.BRONZE_HARNESS, xi.item.ROBE, xi.item.TUNIC, xi.item.LEATHER_VEST, xi.item.ROBE, xi.item.KENPOGI)\n                        end\n                    else -- Over time. Quest failed.\n                        return quest:progressEvent(102)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [96] = function(player, csid, option, npc) -- Quest completed\n                    if quest:complete(player) then\n                        quest:setMustZone(player)\n                    end\n                end,\n\n                [102] = function(player, csid, option, npc) -- Quest failed.\n                    player:delQuest(xi.questLog.WINDURST, xi.quest.id.windurst.A_POSE_BY_ANY_OTHER_NAME)\n                    quest:setVar(player, 'Prog', 0)\n                    quest:setVar(player, 'Wait', 0)\n                    quest:setVar(player, 'Option', 0)\n                    player:addTitle(xi.title.LOWER_THAN_THE_LOWEST_TUNNEL_WORM)\n                    player:needToZone(true)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest Completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Angelica'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getMustZone(player) then\n                        return quest:event(101):setPriority(101)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/A_Smudge_on_Ones_Record.lua"]={["Path"]="scripts/quests/windurst/A_Smudge_on_Ones_Record.lua",["SHA256"]="b87e07a334f1ed82eb9bd94f245a8f879db0e54cf6aa42e6ad4cd04b2b34f366",["Text"]="-----------------------------------\n-- A Smudge on One's Record\n-----------------------------------\n-- !addquest 2 12\n-- Hariga-Origa : !pos -62 -6 105 238\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.A_SMUDGE_ON_ONES_RECORD)\n\nquest.reward =\n{\n    keyItem  = xi.keyItem.MAP_OF_FEIYIN,\n    fameArea = xi.fameArea.WINDURST,\n    fame     = 40,\n    gil      = 5000,\n    exp      = 2000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CHASING_TALES) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 4 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Hariga-Origa'] = quest:progressEvent(413, 0, xi.item.VIAL_OF_SLIME_OIL, xi.item.FROST_TURNIP),\n\n            onEventFinish =\n            {\n                [413] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Hariga-Origa'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.VIAL_OF_SLIME_OIL, xi.item.FROST_TURNIP }) then\n                        return quest:progressEvent(417, quest.reward.gil)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(414, 0, xi.item.VIAL_OF_SLIME_OIL, xi.item.FROST_TURNIP)\n                end,\n            },\n\n            ['Serukoko'] = quest:progressEvent(415, 0, xi.item.VIAL_OF_SLIME_OIL, xi.item.FROST_TURNIP),\n\n            onEventFinish =\n            {\n                [417] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Hariga-Origa'] = quest:event(418):importantOnce(),\n            ['Serukoko']     = quest:event(419):importantOnce(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Acting_in_Good_Faith.lua"]={["Path"]="scripts/quests/windurst/Acting_in_Good_Faith.lua",["SHA256"]="07ec8e20124971e694a9a53f73d33ae794a3c1b20de62481f3814f70a760c536",["Text"]="-----------------------------------\n-- Acting in Good Faith\n-----------------------------------\n-- !addquest 2 64\n-- Gantineux : !pos -83 -9 3 238\n-- Eperdur   : !pos 129 -6 96 231\n-- QM1       : !pos -460.85, -1.5, 425.14 (D-5)\n--           : !pos -24.10, -9.303, 258.993 (I-7)\n--           : !pos -19.624,-1.631,60.368 (I-10)\n--           : !pos 256.757, -20.489, 335.920 (M-6)\n-----------------------------------\nlocal eldiemeID = zones[xi.zone.THE_ELDIEME_NECROPOLIS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.ACTING_IN_GOOD_FAITH)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.SCROLL_OF_TELEPORT_MEA,\n    title    = xi.title.PILGRIM_TO_MEA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 4 and\n                player:getMainLvl() >= 10\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Gantineux'] = quest:progressEvent(10019),\n\n            onEventFinish =\n            {\n                [10019] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.SPIRIT_INCENSE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Gantineux'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SPIRIT_INCENSE) then\n                        return quest:event(10020)\n                    elseif player:hasKeyItem(xi.keyItem.GANTINEUXS_LETTER) then\n                        return quest:event(10022)\n                    else\n                        return quest:progressEvent(10021)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10021] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.GANTINEUXS_LETTER)\n                end,\n            },\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SPIRIT_INCENSE) then\n                        return quest:progressEvent(50)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [50] = function(player, csid, option, npc)\n                    player:messageSpecial(eldiemeID.text.SPIRIT_INCENSE_EMITS_PUTRID_ODOR, xi.keyItem.SPIRIT_INCENSE)\n                    player:delKeyItem(xi.keyItem.SPIRIT_INCENSE)\n\n                    npc:setPos(unpack(eldiemeID.npc.QM1_POS[math.randomInt(1, 4)])) -- move QM1 randomly on quest completion\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Eperdur'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.GANTINEUXS_LETTER) then\n                        return quest:progressEvent(680)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [680] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.GANTINEUXS_LETTER)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Gantineux'] = quest:event(10023):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/All_At_Sea.lua"]={["Path"]="scripts/quests/windurst/All_At_Sea.lua",["SHA256"]="163972a97f9272b60959050f089a910b237f15d806c0d00bb4495878ae79687f",["Text"]="-----------------------------------\n-- All at Sea\n-----------------------------------\n-- Log ID: 2, Quest ID: 23\n-- Paytah      !pos 77.609 -5.000 119.549\n-- Baren-Moren !pos -66.226 -2.009 -148.883\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.ALL_AT_SEA)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.LEATHER_RING,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 3\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Paytah'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(291)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.RIPPED_CAP) then\n                        return quest:progressEvent(292)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [292] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Odilia'] = quest:event(294),\n\n            ['Paytah'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(293)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.SAILORS_CAP) then\n                        return quest:progressEvent(295)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [295] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Baren-Moren'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 1 then\n                        return quest:event(548, 0, xi.item.DHALMEL_HIDE)\n                    elseif progress == 2 then\n                        return quest:event(550, xi.item.SAILORS_CAP, xi.item.DHALMEL_HIDE)\n                    else\n                        return\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        progress == 0 and\n                        npcUtil.tradeHas(trade, xi.item.RIPPED_CAP)\n                    then\n                        return quest:progressEvent(547, 0, xi.item.DHALMEL_HIDE)\n                    elseif\n                        progress >= 1 and\n                        npcUtil.tradeHas(trade, { { xi.item.DHALMEL_HIDE, 4 } }) and\n                        not player:hasItem(xi.item.SAILORS_CAP)\n                    then\n                        if progress == 1 then\n                            return quest:progressEvent(549) -- First time getting the Sailor's Cap\n                        elseif progress == 2 then\n                            return quest:progressEvent(549, 0, 0, 1) -- Everytime after\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [547] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [549] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:confirmTrade()\n                        npcUtil.giveItem(player, xi.item.SAILORS_CAP)\n                        npcUtil.giveItem(player, xi.item.DHALMEL_MANTLE)\n                        quest:setVar(player, 'Prog', 2)\n                    elseif option == 1 then\n                        player:confirmTrade()\n                        npcUtil.giveItem(player, xi.item.SAILORS_CAP)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                quest:getMustZone(player)\n        end,\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Odilia'] = quest:event(297),\n\n            ['Paytah'] = quest:event(296),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Blast_from_the_Past.lua"]={["Path"]="scripts/quests/windurst/Blast_from_the_Past.lua",["SHA256"]="15577b454a58f338727e83cfc24ff30222fb74980a0aa0d3182777fb401243cc",["Text"]="-----------------------------------\n-- Blast from the Past\n-----------------------------------\n-- Log ID: 2, Quest ID: 11\n-- Koru-Moru : !pos -120 -6 124 239\n-----------------------------------\nlocal shakhramiID = zones[xi.zone.MAZE_OF_SHAKHRAMI]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.BLAST_FROM_THE_PAST)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.GREAT_CLUB,\n    title    = xi.title.FOSSILIZED_SEA_FARER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.STAR_STRUCK) and\n                player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION) ~= xi.questStatus.QUEST_ACCEPTED and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 3 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Koru-Moru'] = quest:progressEvent(214),\n\n            onEventFinish =\n            {\n                [214] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Koru-Moru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.BURNITE_SHELL_STONE) then\n                        return quest:progressEvent(224)\n                    else\n                        return quest:event(225)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 2 then\n                        return quest:event(215)\n                    else\n                        return quest:event(216)\n                    end\n                end,\n            },\n\n            ['Yoran-Oran'] =\n            {\n                onTrigger = function(player, npc)\n                    local questOption = quest:getVar(player, 'Option')\n\n                    if questOption == 1 then\n                        return quest:progressEvent(221)\n                    elseif questOption == 2 then\n                        return quest:event(222):importantEvent()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [221] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 2)\n                end,\n\n                [224] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n\n                        xi.quest.setMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.NOTHING_MATTERS)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Tokaka'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(318)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [318] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n\n        [xi.zone.MAZE_OF_SHAKHRAMI] =\n        {\n            ['Fossil_Rock'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: Break out Fossil Rock into multiple NPC names and update impacted\n                    -- quests and missions.\n                    local rockOffset = npc:getID() - shakhramiID.npc.FOSSIL_ROCK_OFFSET\n\n                    if rockOffset == 8 then\n                        if\n                            not GetMobByID(shakhramiID.mob.ICHOROUS_IRE):isSpawned() and\n                            not player:hasItem(xi.item.BURNITE_SHELL_STONE)\n                        then\n                            SpawnMob(shakhramiID.mob.ICHOROUS_IRE):updateClaim(player)\n                        else\n                            player:messageSpecial(shakhramiID.text.FOSSIL_EXTRACTED + 2)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.NOTHING_MATTERS)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Yoran-Oran'] = quest:event(223):importantEvent(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Blood_and_Glory.lua"]={["Path"]="scripts/quests/windurst/Blood_and_Glory.lua",["SHA256"]="e8f939c71de0cb2cdb8fba656241e63929c75418501c41156aa563ac7ccec1ad",["Text"]="-----------------------------------\n-- Blood and Glory\n-- Shantotto !pos 122 -2 112 239\n-- qm3 !pos 119 20 144 205\n-----------------------------------\nlocal windurstWallsID  = zones[xi.zone.WINDURST_WALLS]\nlocal ifritsCauldronID = zones[xi.zone.IFRITS_CAULDRON]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.BLOOD_AND_GLORY)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.POLE_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.STAFF) / 10 >= 230 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(445):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [445] = function(player, csid, option, npc)\n                    if\n                        player:hasItem(xi.item.POLE_OF_TRIALS) or\n                        npcUtil.giveItem(player, xi.item.POLE_OF_TRIALS)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Shantotto'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(450) -- complete\n                    elseif player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        return quest:event(449) -- cont 2\n                    else\n                        return quest:event(446, 0, xi.item.POLE_OF_TRIALS, 0, 0, player:hasItem(xi.item.POLE_OF_TRIALS) and 2 or 0) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.POLE_OF_TRIALS) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(447) -- unfinished weapon\n                        else\n                            return quest:progressEvent(448, 0, 0, xi.keyItem.ANNALS_OF_TRUTH) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [446] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.POLE_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.POLE_OF_TRIALS)\n                    elseif option == 3 then\n                        player:delQuest(xi.questLog.WINDURST, xi.quest.id.windurst.BLOOD_AND_GLORY)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [448] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [450] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.RETRIBUTION)\n                        player:messageSpecial(windurstWallsID.text.RETRIBUTION_LEARNED)\n                        player:setPos(121, -3, 111)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.IFRITS_CAULDRON] =\n        {\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, ifritsCauldronID.mob.CAILLEACH_BHEUR, { hide = 0 })\n                    then\n                        return quest:messageSpecial(ifritsCauldronID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Cailleach_Bheur'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Blue_Ribbon_Blues.lua"]={["Path"]="scripts/quests/windurst/Blue_Ribbon_Blues.lua",["SHA256"]="b85363a0f6a83e179250e162640559b35ff011831e79c127aa3b22400bcf0d44",["Text"]="-----------------------------------\n-- Blue Ribbon Blues\n-----------------------------------\n-- !addquest 2 17\n-- Kerutoto   : !pos 13 -5 -157 238\n-- Roberta    : !pos 21 -4 -157 241\n-- Hume Bones : !pos 299 0.1 19 195\n-----------------------------------\nlocal eldiemeID = zones[xi.zone.THE_ELDIEME_NECROPOLIS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.BLUE_RIBBON_BLUES)\n\nquest.reward =\n{\n    fame  = 50,\n    fameArea = xi.fameArea.WINDURST,\n    title = xi.title.GHOSTIE_BUSTER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.WATER_WAY_TO_GO) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 5 and\n                not xi.quest.getMustZone(player, xi.questLog.WINDURST, xi.quest.id.windurst.WATER_WAY_TO_GO)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kerutoto'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.PURPLE_RIBBON) then\n                        return quest:progressEvent(358, 3600)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(357):oncePerZone()\n                end,\n            },\n\n            onEventFinish =\n            {\n                [357] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [358] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:addGil(3600)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 0)\n                    quest:setVar(player, 'Timer', GetSystemTime() + 60)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Roberta'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:findItem(xi.item.PURPLE_RIBBON) then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 1 then\n                            return quest:progressEvent(376, 0, xi.item.PURPLE_RIBBON)\n                        else\n                            return quest:progressEvent(377, 0, xi.item.PURPLE_RIBBON)\n                        end\n                    else\n                        return quest:progressEvent(379)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [376] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveItem(player, xi.item.PURPLE_RIBBON)\n                    end\n                end,\n\n                [377] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveItem(player, xi.item.PURPLE_RIBBON)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Player has accepted the quest following Kerutoto trade event.  Due to the amount of interaction prior\n    -- to accepting, the Prog variable is reset to 0 when transitioning to this block.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS] =\n        {\n            ['Hume_Bones'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.PURPLE_RIBBON) and\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.popFromQM(player, npc, eldiemeID.mob.LICH_C_MAGNUS, { hide = 0 })\n                    then\n                        player:confirmTrade()\n                        return quest:messageSpecial(eldiemeID.text.RETURN_RIBBON_TO_HER)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getLocalVar(player, 'Prog') == 2 then\n                        -- For onTrigger, there must be a quest function returned to avoid hitting the\n                        -- default action.  Handle the item obtained messageSpecials here.\n\n                        if npcUtil.giveItem(player, xi.item.BLUE_RIBBON, { silent = true }) then\n                            quest:setVar(player, 'Prog', 3)\n                            return quest:messageSpecial(eldiemeID.text.ITEM_OBTAINED, xi.item.BLUE_RIBBON)\n                        else\n                            return quest:messageSpecial(eldiemeID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.BLUE_RIBBON)\n                        end\n                    end\n                end,\n            },\n\n            ['Lich_C_Magnus'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    -- player:addTitle(xi.title.LICH_BANISHER)\n\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setLocalVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kerutoto'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.PURPLE_RIBBON) and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        return quest:progressEvent(365)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        if GetSystemTime() < quest:getVar(player, 'Timer') then\n                            return quest:progressEvent(359)\n                        else\n                            return quest:progressEvent(360)\n                        end\n                    elseif questProgress == 1 then\n                        if not player:findItem(xi.item.PURPLE_RIBBON) then\n                            return quest:progressEvent(366, 0, xi.item.PURPLE_RIBBON)\n                        else\n                            return quest:progressEvent(361, 0, xi.item.PURPLE_RIBBON)\n                        end\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(362)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [360] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.PURPLE_RIBBON) then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [365] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 0)\n                    quest:setVar(player, 'Timer', GetSystemTime() + 60)\n                end,\n\n                [362] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setMustZone(player)\n                    end\n                end\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Roberta'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') < 3 and\n                        not player:findItem(xi.item.PURPLE_RIBBON)\n                    then\n                        return quest:progressEvent(377, 0, xi.item.PURPLE_RIBBON)\n                    else\n                        return quest:progressEvent(380)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [377] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveItem(player, xi.item.PURPLE_RIBBON)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Kerutoto'] = quest:event(363):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/windurst/Chasing_Tales.lua"]={["Path"]="scripts/quests/windurst/Chasing_Tales.lua",["SHA256"]="271fbba228193926663bd5bc334dc35ac0317df500d91b3b96e851c3b3cee4a0",["Text"]="-----------------------------------\n-- Chasing Tales\n-----------------------------------\n-- !addquest 2 13\n-- Tosuka-Porika   : !pos -26 -6 103 238\n-- Furakku-Norakku : !pos -19 -5 101 238\n-- Hae Jakkya      : !pos 57.387 -2.5 -140.757 241\n-- Hae Jakhya      : !pos -75.36 -7.4 -23.82 230\n-- TODO: This quest could be simplified with expanded use of Prog questVar.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.WINDURST, xi.quest.id.windurst.CHASING_TALES)\n\nquest.reward =\n{\n    fame = 30,\n    fameArea = xi.fameArea.WINDURST,\n    gil = 2800,\n    title = xi.title.SAVIOR_OF_KNOWLEDGE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.EARLY_BIRD_CATCHES_THE_BOOKWORM) and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 3 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Tosuka-Porika'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: Requirements for availability need to be verified, and was referenced at the below location.  Left\n                    -- in this block to make it easier to remove if it turns out to be inaccurate.\n                    -- https://ffxiclopedia.fandom.com/wiki/Chasing_Tales\n                    if\n                        player:getNation() ~= xi.nation.WINDURST or\n                        player:getCurrentMission(xi.mission.log_id.WINDURST) ~= xi.mission.id.windurst.THE_JESTER_WHOD_BE_KING\n                    then\n                        return quest:progressEvent(403)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [403] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hae_Jakhya'] =\n            {\n                onTrigger = function(player, npc)\n                    local hasBookKeyItem = player:hasKeyItem(xi.keyItem.A_SONG_OF_LOVE)\n\n                    if\n                        not hasBookKeyItem and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        return quest:progressEvent(611)\n                    elseif hasBookKeyItem then\n                        return quest:progressEvent(612, 0, xi.keyItem.A_SONG_OF_LOVE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [611] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.A_SONG_OF_LOVE)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Tosuka-Porika'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(406)\n                    else\n                        return quest:progressEvent(412)\n                    end\n                end,\n            },\n\n            ['Furakku-Norakku'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.OVERDUE_BOOK_NOTIFICATION_CHASING_TALES) then\n                        return quest:progressEvent(404, 0, xi.keyItem.A_SONG_OF_LOVE)\n                    elseif not player:hasKeyItem(xi.keyItem.A_SONG_OF_LOVE) then\n                        if quest:getVar(player, 'Prog') == 1 then\n                            return quest:progressEvent(409)\n                        elseif player:hasKeyItem(xi.keyItem.OVERDUE_BOOK_NOTIFICATION_CHASING_TALES) then\n                            return quest:progressEvent(405, 0, 126)\n                        end\n                    elseif player:hasKeyItem(xi.keyItem.A_SONG_OF_LOVE) then\n                        return quest:progressEvent(410)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [404] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.OVERDUE_BOOK_NOTIFICATION_CHASING_TALES)\n                end,\n\n                [410] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.OVERDUE_BOOK_NOTIFICATION_CHASING_TALES)\n                        player:delKeyItem(xi.keyItem.A_SONG_OF_LOVE)\n                        player:setLocalVar('Quest[2][12]mustZone', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['An_Polaali'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.A_SONG_OF_LOVE) then\n                        return quest:progressEvent(407)\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(404)\n                    end\n                end,\n            },\n\n            ['An_Shanaa'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.A_SONG_OF_LOVE) then\n                        return quest:progressEvent(408, 0, xi.keyItem.A_SONG_OF_LOVE)\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(405)\n                    end\n                end,\n            },\n\n            ['Hae_Jakkya'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.A_SONG_OF_LOVE) then\n                        return quest:progressEvent(406)\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(403, 0, xi.keyItem.A_SONG_OF_LOVE)\n                    elseif player:hasKeyItem(xi.keyItem.OVERDUE_BOOK_NOTIFICATION_CHASING_TALES) then\n                        return quest:progressEvent(402, 0, xi.keyItem.A_SONG_OF_LOVE)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [402] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Furakku-Norakku'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('Quest[2][12]mustZone') == 1 then\n                        return quest:event(411):replaceDefault()\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['An_Polaali'] = quest:event(407):importantOnce(),\n            ['An_Shanaa'] = quest:event(408, 0, 126):importantOnce(),\n            ['Hae_Jakkya'] = quest:event(406):importantOnce(),\n        },\n    },\n}\n\nreturn quest\n"}};
